def frame_stats(s, strand, frame, start_off):
    # s is the codon-window string starting at the frame start; frame is 0..2
    orfs = []
    i = 0
    n = len(s)//3
    while i < n:
        c = s[i*3:i*3+3]
        if c == "ATG":
            # scan for stop
            j = i
            len_aa = 0
            while j < n:
                if s[j*3:j*3+3] in ("TAA","TAG","TGA"):
                    break
                j += 1; len_aa += 1
            if len_aa >= 80:
                cds_start = start_off + i*3 + 1  # 1-based genomic
                cds_end = start_off + (j*3+2)
                orfs.append((strand, frame, cds_start, cds_end, len_aa, start_off))
            i = j+1
        else:
            i += 1
    return orfs

